use std::rc::Rc;

const BITS: u32 = 5;
const WIDTH: usize = 1 << BITS;
const MASK: usize = WIDTH - 1;

#[derive(Clone, Debug)]
enum Node<T> {
    Branch(Rc<Vec<Node<T>>>),
    Leaf(Rc<Vec<T>>),
}

#[derive(Clone, Debug)]
pub struct Vector<T> {
    len: usize,
    shift: u32,
    root: Node<T>,
    tail: Rc<Vec<T>>,
}

impl<T: Clone> Vector<T> {
    pub fn new() -> Self {
        Vector {
            len: 0,
            shift: BITS,
            root: Node::Branch(Rc::new(Vec::new())),
            tail: Rc::new(Vec::new()),
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    fn tail_off(&self) -> usize {
        self.len - self.tail.len()
    }

    pub fn push_back(&self, v: T) -> Self {
        if self.tail.len() < WIDTH {
            let mut t = Vec::with_capacity(WIDTH);
            t.extend_from_slice(&self.tail);
            t.push(v);
            return Vector {
                len: self.len + 1,
                shift: self.shift,
                root: self.root.clone(),
                tail: Rc::new(t),
            };
        }
        // tail is full: push it into the trie as a leaf
        let leaf = Node::Leaf(self.tail.clone());
        let leaf_count = self.tail_off() >> BITS; // leaves already in trie
        let capacity = 1usize << self.shift; // leaves the current root can hold
        let (root, shift) = if leaf_count == capacity {
            let mut nr = Vec::with_capacity(WIDTH);
            nr.push(self.root.clone());
            nr.push(new_path(self.shift, leaf));
            (Node::Branch(Rc::new(nr)), self.shift + BITS)
        } else {
            (push_leaf(self.shift, &self.root, leaf_count, leaf), self.shift)
        };
        let mut t = Vec::with_capacity(WIDTH);
        t.push(v);
        Vector { len: self.len + 1, shift, root, tail: Rc::new(t) }
    }

    pub fn get(&self, i: usize) -> Option<&T> {
        if i >= self.len {
            return None;
        }
        let toff = self.tail_off();
        if i >= toff {
            return self.tail.get(i - toff);
        }
        let mut node = &self.root;
        let mut s = self.shift;
        loop {
            match node {
                Node::Branch(c) => {
                    node = &c[(i >> s) & MASK];
                    if s == BITS {
                        break;
                    }
                    s -= BITS;
                }
                Node::Leaf(_) => break,
            }
        }
        match node {
            Node::Leaf(l) => l.get(i & MASK),
            _ => None,
        }
    }
}

fn new_path<T: Clone>(shift: u32, node: Node<T>) -> Node<T> {
    if shift == BITS {
        node
    } else {
        let mut v = Vec::with_capacity(WIDTH);
        v.push(new_path(shift - BITS, node));
        Node::Branch(Rc::new(v))
    }
}

/// Insert `leaf` at leaf-index `leaf_count` under `parent` (which spans `shift`).
fn push_leaf<T: Clone>(shift: u32, parent: &Node<T>, leaf_count: usize, leaf: Node<T>) -> Node<T> {
    let ch = match parent {
        Node::Branch(c) => c,
        Node::Leaf(_) => unreachable!(),
    };
    let mut nc = Vec::with_capacity(WIDTH);
    nc.extend_from_slice(ch);
    if shift == BITS {
        nc.push(leaf);
    } else {
        let sub_cap = 1usize << (shift - BITS); // leaves per child subtree
        let idx = leaf_count / sub_cap;
        if idx < nc.len() {
            let sub = push_leaf(shift - BITS, &nc[idx], leaf_count % sub_cap, leaf);
            nc[idx] = sub;
        } else {
            nc.push(new_path(shift - BITS, leaf));
        }
    }
    Node::Branch(Rc::new(nc))
}

fn main() {
    let n: usize = std::env::args().nth(1).map(|s| s.parse().unwrap()).unwrap_or(5);
    let mut v = Vector::new();
    for i in 0..n {
        v = v.push_back(i as i32);
    }
    println!("{}", v.len());
    if n > 0 {
        for i in 0..n.min(5000) {
            assert_eq!(v.get(i), Some(&(i as i32)), "idx {}", i);
        }
        for &i in &[0usize, 31, 32, 33, 1023, 1024, 1025, 32767, 32768, 32769, 1048576, n - 1] {
            if i < n {
                assert_eq!(v.get(i), Some(&(i as i32)), "idx {}", i);
            }
        }
        assert_eq!(v.get(n), None);
        eprintln!("index checks OK (n={})", n);
    }
}

