// Feature-compatibility probe: must compile under BOTH `rustc` (edition 2015)
// and `rustc --edition 2021`.
#![forbid(unsafe_code)]
#![allow(dead_code)]

#[path = "m/mod.rs"]
mod m;

use self::m::Thing;
use std::convert::TryFrom; // NOT in prelude before edition 2021

fn main() {
    let t = Thing::new();
    // impl Trait in return position
    let s: usize = t.iter().count();
    // dyn trait object
    let b: Box<dyn Iterator<Item = i32>> = Box::new(t.iter());
    let c = b.count();
    // FromIterator / collect into the custom type
    let t2: Thing = (0i32..4).collect();
    // TryFrom
    let x = i32::try_from(7i64).unwrap();
    // matches!
    let m = matches!(x, 7);
    // slice iteration by reference (array into_iter differs across editions -> use &[..])
    let arr = [1i32, 2, 3];
    let sum: i32 = arr.iter().sum();
    println!("{} {} {} {} {} {}", s, c, t2.len(), x, m, sum);
}

use std::rc::Rc;

pub struct Thing {
    items: Rc<Vec<i32>>,
}

impl Thing {
    pub fn new() -> Self {
        Thing { items: Rc::new(vec![1, 2, 3]) }
    }

    pub fn len(&self) -> usize {
        self.items.len()
    }

    // `impl Trait` in return position, with a lifetime tie
    pub fn iter<'a>(&'a self) -> impl Iterator<Item = i32> + 'a {
        self.items.iter().cloned()
    }
}

impl std::iter::FromIterator<i32> for Thing {
    fn from_iter<I: IntoIterator<Item = i32>>(iter: I) -> Self {
        Thing { items: Rc::new(iter.into_iter().collect()) }
    }
}

impl<'a> IntoIterator for &'a Thing {
    type Item = i32;
    type IntoIter = Box<dyn Iterator<Item = i32> + 'a>;
    fn into_iter(self) -> Self::IntoIter {
        Box::new(self.items.iter().cloned())
    }
}

#[cfg(test)]
mod tests {
    use super::Thing;

    #[test]
    fn it_works() {
        assert_eq!(Thing::new().len(), 3);
    }
}

